  });

  it("does not derive for a conflicted pull request", async () => {
    const routes = scenario({
      ancestor: [{ path: "shared.txt", sha: A }],
      base: [{ path: "shared.txt", sha: A }],
      head: [{ path: "shared.txt", sha: B2 }],
      pull: { mergeable: false },
    });
