            state: "open",
            draft: false,
            mergeable: true,
            merge_commit_sha: STALE_CANDIDATE,
            base: { ref: "main", sha: BASE, repo: { id: 1315419165 } },
            head: { sha: HEAD, repo: { id: 1315419165 } },
